def summarize(a,surface,thermo,ex):
 primary=[r for r in a['steps'] if 61200<=r['source_seconds']<64800];s=a['primary_hour_processes_kg_m2'];qc=s['QCLOUD'];qv=s['QVAPOR'];water=s['all_seven_species'];w=a['first_complete_loss_step'];peak=a['largest_cloud_loss_step']
